def rects(g, v):
    H=len(g);W=len(g[0]); out=[]
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if g[i][j]==v and not seen[i][j]:
                st=[(i,j)]; comp=[]
                while st:
                    a,b=st.pop()
                    if seen[a][b]: continue
                    seen[a][b]=True; comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==v and not seen[x][y]: st.append((x,y))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                out.append((min(rs),max(rs),min(cs),max(cs),len(comp)))
    return sorted(out,key=lambda x:-x[4])

