    for i in range(H):
        for j in range(W):
            if g[i][j]!=0 and (i,j) not in seen:
                # flood of same color
                stack=[(i,j)]; seen.add((i,j)); pts=[]
                while stack:
                    p=stack.pop(); pts.append(p)
                    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(p[0]+di,p[1]+dj)
                        if 0<=q[0]<H and 0<=q[1]<W and g[q[0]][q[1]]==g[i][j] and q not in seen:
